params.command:
$ErrorActionPreference='Stop'
$repo='fengie/mhw-mods'
$git=(Get-Command git.exe -ErrorAction Stop).Source
$request="protocol=https`nhost=github.com`n`n"
$cred=($request | & $git credential fill 2>$null)
$token=$null
foreach($line in @($cred)){ if($line -like 'password=*'){ $token=$line.Substring(9); break } }
$cred=$null
if([string]::IsNullOrWhiteSpace($token)){ throw 'Git credential manager did not provide a GitHub token' }
$headers=@{Accept='application/vnd.github+json';Authorization="Bearer $token";'X-GitHub-Api-Version'='2022-11-28';'User-Agent'='Heaven-CI-Reconciler'}
try {
  $runs=(Invoke-RestMethod -Headers $headers -Uri "https://api.github.com/repos/$repo/actions/runs?branch=main&per_page=100").workflow_runs
  $names=@('Heaven Local Bridge Gate','Heaven Control Plane Gate')
  $report=@()
  foreach($name in $names){
    $active=@($runs | Where-Object { $_.name -eq $name -and $_.status -in @('queued','pending','waiting','requested') } | Sort-Object created_at -Descending)
    if($active.Count -eq 0){ continue }
    $keep=$active[0]
    $report += [pscustomobject]@{workflow=$name; action='keep'; run_id=$keep.id; status=$keep.status; sha=$keep.head_sha}
    foreach($run in @($active | Select-Object -Skip 1)){
      try {
        Invoke-RestMethod -Method POST -Headers $headers -Uri "https://api.github.com/repos/$repo/actions/runs/$($run.id)/cancel" | Out-Null
        $report += [pscustomobject]@{workflow=$name; action='cancel'; run_id=$run.id; status=$run.status; sha=$run.head_sha}
      } catch {
        $report += [pscustomobject]@{workflow=$name; action='cancel-failed'; run_id=$run.id; status=$run.status; sha=$run.head_sha; error=$_.Exception.Message}
      }
    }
  }
  $report | ConvertTo-Json -Depth 4
} finally {
  $headers.Authorization=$null
  $token=$null
}
